for ref in doc.references:
    if ref.reference_doctype == "Sales Invoice":
        booking_name = frappe.db.get_value("Room Booking", {"sales_invoice": ref.reference_name}, "name")
        if not booking_name:
            continue
        outstanding = frappe.db.get_value("Sales Invoice", ref.reference_name, "outstanding_amount")
        frappe.db.set_value("Room Booking", booking_name, "pay_status", "Paid" if outstanding == 0 else "Unpaid")

for ref in doc.references:
    if ref.reference_doctype == "Sales Invoice":
        booking_name = frappe.db.get_value("Room Booking", {"sales_invoice": ref.reference_name}, "name")
        if not booking_name:
            continue
        outstanding = frappe.db.get_value("Sales Invoice", ref.reference_name, "outstanding_amount")
        if outstanding == 0:
            frappe.db.set_value("Room Booking", booking_name, "pay_status", "Paid")

if doc.room and doc.check_in and doc.check_out:
    filters = {
        "room": doc.room,
        "docstatus": ["<", 2],
        "status": ["!=", "Cancelled"],
        "check_in": ["<", doc.check_out],
        "check_out": [">", doc.check_in],
    }

    if doc.name:
        filters["name"] = ["!=", doc.name]

    conflict = frappe.db.exists("Room Booking", filters)

    if conflict:
        frappe.throw(
            f"Номер {doc.room} уже забронирован на этот период (пересекается с бронированием {conflict})"
        )

